import{_ as p,a0 as o,w as d,s as r,ao as l,I as i,x as n,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"三款簡單而優秀的 Linux 網絡監視工具 | LCTT x X-CMD","titleTemplate":false,"description":"三款簡單而優秀的 Linux 網絡監視工具 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三款簡單而優秀的 Linux 網絡監視工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三款簡單而優秀的 Linux 網絡監視工具 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171019 3 Simple Excellent Linux Network Monitors","title":"三款簡單而優秀的 Linux 網絡監視工具","tag":"201801","desc":""},"relativePath":"201801/20171019 3 Simple Excellent Linux Network Monitors.md","filePath":"[post].md"}'),c={name:"201801/20171019 3 Simple Excellent Linux Network Monitors.md"};function u(g,s,h,k,b,f){const a=o("Link");return d(),r("div",null,[s[30]||(s[30]=l(`<h1 id="三款簡單而優秀的-linux-網絡監視工具" tabindex="-1">三款簡單而優秀的 Linux 網絡監視工具 <a class="header-anchor" href="#三款簡單而優秀的-linux-網絡監視工具" aria-label="Permalink to “三款簡單而優秀的 Linux 網絡監視工具”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_3.png?itok=iuPcSN4k" alt="network" title="network"></p><blockquote><p>通過 <code>iftop</code>、 <code>nethogs</code> 和 <code>vnstat</code> 詳細瞭解你的網絡連接狀態。</p></blockquote><p>你可以通過這三個 Linux 命令瞭解當前網絡的大量信息。<code>iftop</code> 通過進程號跟蹤網絡連接，<code>nethogs</code> 快速告知你哪些進程在佔用你的帶寬，而 <code>vnstat</code> 以一個良好的輕量級守護進程在後台運行，並實時記錄你的網絡使用情況。</p><h3 id="iftop" tabindex="-1">iftop <a class="header-anchor" href="#iftop" aria-label="Permalink to “iftop”">​</a></h3><p>令人稱讚的 <code>iftop</code> 可以監聽您指定的網絡接口，並以 top 的樣式呈現。</p><p>這是一個不錯的小工具，可以用於找出網絡擁塞，測速和維持網絡流量總量。看到自己到底在用多少帶寬往往是非常驚人的，尤其是對於我們這些仍然記得電話線路、調製解調器，“高速”到令人驚叫的 kb 和實時波特率的老人們。我們在很久之前就不再使用波特率，轉而鍾情於比特率。波特率用於衡量信號變化，儘管有時候與比特率相同，但大多數情況下並非如此。</p><p>如果你只有一個網絡接口，直接運行 <code>iftop</code> 即可。不過 <code>iftop</code> 需要 root 權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop</span></span></code></pre></div><p>如果你有多個網絡接口，那就指定你要監控的接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop -i wlan0</span></span></code></pre></div><p>就像 <code>top</code> 命令一樣，你可以在命令運行時更改顯示選項：</p><ul><li><code>h</code> 切換幫助界面。</li><li><code>n</code> 是否解析域名。</li><li><code>s</code> 切換源地址的顯示，<code>d</code> 則切換目的地址的顯示。</li><li><code>S</code> 是否顯示端口號。</li><li><code>N</code> 是否解析端口；若關閉解析則顯示端口號。</li><li><code>t</code> 切換文本顯示界面。默認的顯示方式需要 ncurses。我個人認為圖 1 的顯示方式在組織性和可讀性都更加良好。</li><li><code>p</code> 暫停顯示更新。</li><li><code>q</code> 退出程序。</li></ul><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-1_8.png?itok=luKHS5ve" alt="text display" title="text display"></p><p><em>圖 1:組織性和可讀性良好的文本顯示。</em></p><p>當你切換顯示設置的時候，<code>iftop</code> 並不會中斷監測流量。當然你也可以單獨監測一台主機。而這需要該主機的 IP 地址和子網掩碼。現在，我很好奇 Pandora（LCTT 譯註：一家美國的電台公司）能給我貧瘠的帶寬帶來多大的負載。因此我首先使用 dig 命令找到他們的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig A pandora.com</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>;; ANSWER SECTION:</span></span>
<span class="line"><span>pandora.com.            267     IN      A       208.85.40.20</span></span>
<span class="line"><span>pandora.com.            267     IN      A       208.85.40.50</span></span></code></pre></div>`,17)),i("p",null,[s[1]||(s[1]=n("那子網掩碼呢？",-1)),e(a,{href:"https://www.linux.com/learn/intro-to-linux/2017/8/how-calculate-network-addresses-ipcalc"},{default:t(()=>[...s[0]||(s[0]=[n("ipcalc",-1)])]),_:1}),s[2]||(s[2]=n(" 會告訴我們：",-1))]),s[31]||(s[31]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipcalc -b 208.85.40.20</span></span>
<span class="line"><span>Address:   208.85.40.20   </span></span>
<span class="line"><span>Netmask:   255.255.255.0 = 24</span></span>
<span class="line"><span>Wildcard:  0.0.0.255  </span></span>
<span class="line"><span>=&gt;</span></span>
<span class="line"><span>Network:   208.85.40.0/24</span></span></code></pre></div><p>現在，將 IP 地址和子網掩碼提供給 <code>iftop</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop -F 208.85.40.20/24 -i wlan0</span></span></code></pre></div><p>很棒的不是麼？而我也很驚奇地發現，Pandora 在我的網絡上，每小時大約使用 500kb。並且就像大多數流媒體服務一樣，Pandora 的流量在迅速增長，並依靠緩存穩定下來。</p>`,4)),i("p",null,[s[4]||(s[4]=n("你可以使用 ",-1)),s[5]||(s[5]=i("code",null,"-G",-1)),s[6]||(s[6]=n(" 選項對 IPv6 地址執行相同的操作。查閲友好的 man 可以幫助你瞭解 ",-1)),s[7]||(s[7]=i("code",null,"iftop",-1)),s[8]||(s[8]=n(" 的其他功能，包括使用個人配置文件自定義你的默認選項，以及使用自定義過濾（請參閲 ",-1)),e(a,{href:"http://www.tcpdump.org/manpages/pcap-filter.7.html"},{default:t(()=>[...s[3]||(s[3]=[n("PCAP-FILTER",-1)])]),_:1}),s[9]||(s[9]=n(" 來獲取過濾指南）。",-1))]),s[32]||(s[32]=l(`<h3 id="nethogs" tabindex="-1">nethogs <a class="header-anchor" href="#nethogs" aria-label="Permalink to “nethogs”">​</a></h3><p>當你想要快速瞭解是誰在吸取你的帶寬的時候，<code>nethogs</code> 是個快速而簡單的方法。你需要以 root 身份運行並指定要監聽的接口。它會給你顯示大量的應用程序及其進程號，所以如果你想的話，你可以藉此殺死任一進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nethogs wlan0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nethogs version 0.8.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PID USER   PROGRAM              DEV    SENT   RECEIVED       </span></span>
<span class="line"><span>7690 carla /usr/lib/firefox     wlan0 12.494 556.580 KB/sec</span></span>
<span class="line"><span>5648 carla .../chromium-browser wlan0  0.052   0.038 KB/sec</span></span>
<span class="line"><span>TOTAL                                 12.546 556.618 KB/sec</span></span></code></pre></div><p><code>nethogs</code> 並沒有多少選項：在 kb/s、kb、b、mb之間循環，按接收和發送的數據包排序，調整刷新延遲。具體請看<code>man nethogs</code>，或者是運行 <code>nethogs -h</code>。</p><h3 id="vnstat" tabindex="-1">vnstat <a class="header-anchor" href="#vnstat" aria-label="Permalink to “vnstat”">​</a></h3>`,5)),i("p",null,[e(a,{href:"http://humdi.net/vnstat/"},{default:t(()=>[...s[10]||(s[10]=[n("vnstat",-1)])]),_:1}),s[11]||(s[11]=n("是最容易使用的網絡數據收集工具。它十分輕量並且不需要 root 權限。它以守護進程在後台運行，因此可以實時地記錄你的網絡數據。單個 ",-1)),s[12]||(s[12]=i("code",null,"vnstat",-1)),s[13]||(s[13]=n(" 命令就可以顯示所累計的數據。",-1))]),s[33]||(s[33]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan0</span></span>
<span class="line"><span>Database updated: Tue Oct 17 08:36:38 2017</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   wlan0 since 10/17/2017</span></span>
<span class="line"><span></span></span>
<span class="line"><span>          rx:  45.27 MiB      tx:  3.77 MiB      total:  49.04 MiB</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   monthly</span></span>
<span class="line"><span>                     rx      |     tx      |    total    |   avg. rate</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>       Oct &#39;17     45.27 MiB |    3.77 MiB |   49.04 MiB |    0.28 kbit/s</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>     estimated        85 MiB |       5 MiB |      90 MiB |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   daily</span></span>
<span class="line"><span>                     rx      |     tx      |    total    |   avg. rate</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>         today     45.27 MiB |    3.77 MiB |   49.04 MiB |   12.96 kbit/s</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>     estimated       125 MiB |       8 MiB |     133 MiB |</span></span></code></pre></div><p>默認情況下它會顯示所有的網絡接口。使用 <code>-i</code> 選項來選擇某個接口。也可以像這樣合併多個接口的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan0+eth0+eth1</span></span></code></pre></div><p>你可以通過這幾種方式過濾數據顯示：</p><ul><li><code>-h</code> 按小時顯示統計信息。</li><li><code>-d</code> 按天顯示統計信息.</li><li><code>-w</code> 和 <code>-m</code> 分別按周和月份來顯示統計信息。</li><li>使用 <code>-l</code> 選項查看實時更新。</li></ul><p>以下這條命令將會刪除 wlan1 的資料庫並不再監視它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan1 --delete</span></span></code></pre></div><p>而下面這條命令將會為你的一個網絡接口創建一個別名。這個例子使用了 Ubuntu 16.04 的一個有線接口名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -u -i enp0s25 --nick eth0</span></span></code></pre></div><p>默認情況下，vnstat 會監視 eth0。你可以在 <code>/etc/vnstat.conf</code> 對它進行修改，或者在你的家目錄下創建你自己的個人配置文件。請參閲 <code>man vnstat</code> 以獲取完整的指南。</p><p>你也可以安裝 <code>vnstati</code> 來創建簡單的彩圖（圖 2）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstati -s -i wlx7cdd90a0a1c2 -o vnstat.png</span></span></code></pre></div><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-2_5.png?itok=HsWJMcW0" alt="vnstati" title="vnstati"></p><p><em>圖 2:你可以使用vnstati來創建簡單的彩圖。</em></p><p>請參閲 <code>man vnstati</code> 以獲取完整的選項。</p>`,15)),i("p",null,[i("em",null,[s[15]||(s[15]=n("欲瞭解 Linux 的更多信息，可以通過學習 Linux 基金會和 edX 的免費課程，",-1)),e(a,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:t(()=>[...s[14]||(s[14]=[n("“Linux 入門”",-1)])]),_:1}),s[16]||(s[16]=n("。",-1))])]),s[34]||(s[34]=i("hr",null,null,-1)),i("p",null,[s[18]||(s[18]=n("via: ",-1)),e(a,{href:"https://www.linux.com/learn/intro-to-linux/2017/10/3-simple-excellent-linux-network-monitors"},{default:t(()=>[...s[17]||(s[17]=[n("https://www.linux.com/learn/intro-to-linux/2017/10/3-simple-excellent-linux-network-monitors",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=n("作者：",-1)),e(a,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[19]||(s[19]=[n("CARLA SCHRODER",-1)])]),_:1}),s[23]||(s[23]=n(" 譯者：",-1)),e(a,{href:"https://github.com/KeyLD"},{default:t(()=>[...s[20]||(s[20]=[n("KeyLD",-1)])]),_:1}),s[24]||(s[24]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[21]||(s[21]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[27]||(s[27]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[25]||(s[25]=[n("LCTT",-1)])]),_:1}),s[28]||(s[28]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[26]||(s[26]=[n("Linux中國",-1)])]),_:1}),s[29]||(s[29]=n(" 榮譽推出",-1))])])}const w=p(c,[["render",u]]);export{v as __pageData,w as default};
